sql.where:
wv.deleted = 0

  AND wv.voice_type = #{voiceType}


  AND wv.status = #{status}


  AND wv.company_id = #{companyId}


  AND wv.vessel_id = #{vesselId}


  AND (
       wv.voice_no LIKE '%' + #{keyword} + '%'
    OR wv.title LIKE '%' + #{keyword} + '%'
  )


  AND wv.created_at >= #{dateFrom}


  AND wv.created_at < DATEADD(DAY, 1, #{dateTo})


  AND wv.reporter_anonymous = 0
